import{_ as e,o as a,c as o,a2 as l}from"./chunks/framework.BXzK3EA4.js";const y=JSON.parse('{"title":"04. Methods for Building Embedded Linux Systems","description":"","frontmatter":{},"headers":[],"relativePath":"04-build-methods.md","filePath":"04-build-methods.md"}'),d={name:"04-build-methods.md"};function r(i,t,s,n,g,u){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_04-methods-for-building-embedded-linux-systems" tabindex="-1">04. Methods for Building Embedded Linux Systems <a class="header-anchor" href="#_04-methods-for-building-embedded-linux-systems" aria-label="Permalink to &quot;04. Methods for Building Embedded Linux Systems&quot;">​</a></h1><p>There are three primary strategies for bringing up a Linux system on embedded target hardware:</p><hr><h2 id="strategy-1-downloading-pre-made-vendor-images" tabindex="-1">Strategy 1: Downloading Pre-Made Vendor Images <a class="header-anchor" href="#strategy-1-downloading-pre-made-vendor-images" aria-label="Permalink to &quot;Strategy 1: Downloading Pre-Made Vendor Images&quot;">​</a></h2><p>Downloading a binary <code>.img</code> file from a hardware vendor (e.g., Raspberry Pi OS, Ubuntu Server) and writing it to an SD card.</p><ul><li><strong>Pros:</strong> Fast setup, works immediately out of the box.</li><li><strong>Cons:</strong> Heavy software bloat, long boot times, high storage footprint, unnecessary power consumption, difficult to maintain across thousands of deployed production units.</li></ul><hr><h2 id="strategy-2-manual-source-compilation-glutton-for-punishment" tabindex="-1">Strategy 2: Manual Source Compilation (&quot;Glutton for Punishment&quot;) <a class="header-anchor" href="#strategy-2-manual-source-compilation-glutton-for-punishment" aria-label="Permalink to &quot;Strategy 2: Manual Source Compilation (&quot;Glutton for Punishment&quot;)&quot;">​</a></h2><p>Manually fetching, cross-compiling, and linking toolchains, U-Boot, the Linux kernel, BusyBox, and every required library.</p><ul><li><strong>Pros:</strong> Maximum theoretical understanding of build steps.</li><li><strong>Cons:</strong> Extremely tedious, error-prone, months of resolving cross-compiler dependency conflicts. Impractical for production.</li></ul><hr><h2 id="strategy-3-automated-build-systems-buildroot-yocto-openwrt" tabindex="-1">Strategy 3: Automated Build Systems (Buildroot, Yocto, OpenWRT) <a class="header-anchor" href="#strategy-3-automated-build-systems-buildroot-yocto-openwrt" aria-label="Permalink to &quot;Strategy 3: Automated Build Systems (Buildroot, Yocto, OpenWRT)&quot;">​</a></h2><p>Using specialized embedded build automation suites to generate tailored, minimal root filesystems, kernel binaries, and bootloaders.</p><h3 id="comparison-of-automated-embedded-build-systems" tabindex="-1">Comparison of Automated Embedded Build Systems <a class="header-anchor" href="#comparison-of-automated-embedded-build-systems" aria-label="Permalink to &quot;Comparison of Automated Embedded Build Systems&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Metric / Tool</th><th style="text-align:left;">Buildroot</th><th style="text-align:left;">Yocto Project (Poky/BitBake)</th><th style="text-align:left;">OpenWRT</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary Design Goal</strong></td><td style="text-align:left;">Simplicity &amp; Speed</td><td style="text-align:left;">Enterprise Scalability &amp; Customization</td><td style="text-align:left;">Networking &amp; Router Gear</td></tr><tr><td style="text-align:left;"><strong>Build Paradigm</strong></td><td style="text-align:left;">Single Make-based Makefile</td><td style="text-align:left;">Recipe-based (<code>.bb</code>) Layer system</td><td style="text-align:left;">Package Manager oriented</td></tr><tr><td style="text-align:left;"><strong>Learning Curve</strong></td><td style="text-align:left;">Very Low (Hours/Days)</td><td style="text-align:left;">High (Weeks/Months)</td><td style="text-align:left;">Moderate</td></tr><tr><td style="text-align:left;"><strong>Host Disk Footprint</strong></td><td style="text-align:left;">5 GB – 15 GB</td><td style="text-align:left;">50 GB – 100+ GB</td><td style="text-align:left;">10 GB – 20 GB</td></tr><tr><td style="text-align:left;"><strong>Rebuild Behavior</strong></td><td style="text-align:left;">Rebuilds whole tree on config change</td><td style="text-align:left;">Incremental recipe updates (sstate-cache)</td><td style="text-align:left;">Package feeds update</td></tr><tr><td style="text-align:left;"><strong>Target Update Model</strong></td><td style="text-align:left;">Monolithic OS image flash</td><td style="text-align:left;">Layered image or package feed</td><td style="text-align:left;">On-device package manager (<code>opkg</code>)</td></tr><tr><td style="text-align:left;"><strong>Best Use Case</strong></td><td style="text-align:left;">Single-purpose, fixed-function SBCs</td><td style="text-align:left;">Large fleet deployments, complex OS stacks</td><td style="text-align:left;">Network gateways, routers</td></tr></tbody></table>',15)])])}const c=e(d,[["render",r]]);export{y as __pageData,c as default};
